def reduce_if_selected(path,raw):
 if path not in SOURCE_INPUTS:return raw
 if type(raw)is not bytes:raise ValueError('media binding source bytes required')
 if hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:return raw
 for added,removed in EDITS[path]:
  if raw.count(added)!=1:raise ValueError('media binding inverse changed')
  raw=raw.replace(added,removed,1)
 if hashlib.sha256(raw).hexdigest()!=BASE_PINS[path]:raise ValueError('media binding changed other bytes')
 return raw

def reduce_current(path,raw):
 if path not in SOURCE_INPUTS or type(raw)is not bytes or hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed current media binding')
 return reduce_if_selected(path,raw)
